cat > /etc/nginx/sites-available/myapp << 'EOF'
server {
    listen 80;
    server_name myapp.example.com;
    root /var/www/myapp;
    index index.html;
}
EOF && ln -s /etc/nginx/sites-available/myapp /etc/nginx/sites-enabled/ && nginx -s reload

cat > /etc/nginx/sites-available/proxy << 'EOF'
server {
    listen 80;
    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}
EOF && ln -sf /etc/nginx/sites-available/proxy /etc/nginx/sites-enabled/ && nginx -s reload

echo -e 'limit_req_zone $binary_remote_addr zone=mylimit:10m rate=10r/s;
server {
    location /login {
        limit_req zone=mylimit;
        proxy_pass http://backend;
    }
}' > /etc/nginx/sites-available/ratelimited && nginx -s reload
